\newcommand{\pair}[2]{\langle #1, #2\rangle}
\newcommand{\Pplus}{P^{+}}

\title{A Degree Criterion for Dominance of the Weights\\ $\lambda_{D,I} = 2\rho - \beta_I - \beta_D$ in the Simply-Laced Case}
\author{Aristotle}
\date{2026-07-02}

\begin{document}

\begin{abstract}
We study the dominance of a distinguished family of integral weights arising in the
classification of nearly extremal elements of a fundamental highest-weight crystal of a
symmetrizable Kac--Moody algebra. For a subdiagram $I$ of the Dynkin diagram and a subset
$D \subseteq I$ of \emph{marked} vertices, one forms the weight
$\lambda_{D,I} = 2\rho - \beta_I - \beta_D$, where $\rho$ is the half-sum of the positive roots
and $\beta_S = \sum_{j \in S}\alpha_j$ is the partial sum of simple roots over $S$. Deciding when
$\lambda_{D,I}$ is dominant is the weight-theoretic core of the underlying classification. We
prove that in the \emph{simply-laced} setting---where the generalized Cartan matrix takes the
form $A = 2\,\Id - \Adj(G)$ for a simple graph $G$---the abstract dominance condition is
equivalent to an elementary local inequality on vertex degrees. Explicitly, taking $I$ to be the
entire diagram, $\lambda_{D,I}$ is dominant if and only if every marked vertex $i \in D$
satisfies $\deg i + \deg_D i \ge 2$, where $\deg_D i$ denotes the number of neighbors of $i$
inside $D$. As corollaries we obtain a crisp leaf obstruction (a singleton $\{v\}$ is admissible
iff $\deg v \ge 2$), the automatic dominance of the empty marking, and a characterization
identifying forests as exactly the connected diagrams on which some vertex fails to carry a
dominant singleton. The results reduce a representation-theoretic positivity test to a decidable
graph-combinatorial one.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Motivation}
Let $\mathfrak{g}$ be a symmetrizable Kac--Moody algebra with simple roots
$\{\alpha_i\}_{i \in \mathcal I}$ and simple coroots $\{\coroot{i}\}_{i\in\mathcal I}$. The
integrable highest-weight module $L(\rho)$ with highest weight $\rho$ (the half-sum of positive
roots) has an associated crystal $B(\rho)$. A central object of study is the set of
\emph{$\rho$-dominant} elements of $B(\rho)$: those $b$ for which $\varepsilon_i(b) \le 1$ for
every simple root, i.e.\ each lowering direction can be applied at most once from $b$.

A conjectural classification asserts that every $\rho$-dominant element arises as a canonical
element $\pi_{D,I}$ built from three combinatorial choices:
\begin{enumerate}
  \item a subgraph $I$ of the Dynkin diagram with only simple bonds and no cycle of length $\ge 3$
        (a \emph{simply-laced forest});
  \item a subset $D \subseteq I$ such that the weight $\lambda_{D,I} = 2\rho - \beta_I - \beta_D$
        is \emph{dominant}; and
  \item a choice of root vertex in each connected component of $I$.
\end{enumerate}
The dominance requirement in (2) is the arithmetic gatekeeper of the construction. This paper
isolates and analyzes it completely in the simply-laced case.

\subsection{Contributions}
In the simply-laced setting, where $A = 2\,\Id - \Adj(G)$ for a simple graph $G$, we establish:
closed-form pairings for $\pair{\beta_S}{\coroot{i}}$ (Theorem~\ref{thm:pair}); a dominance
criterion for the whole diagram (Theorem~\ref{thm:dom}); a leaf obstruction
(Theorem~\ref{thm:leaf}); sufficient conditions (Propositions~\ref{prop:empty}
and~\ref{prop:mindeg}); and a forest characterization (Theorem~\ref{thm:forest}). Together they
reduce a representation-theoretic positivity condition to a decidable statement about vertex
degrees.

\section{Setup and definitions}

Throughout, $G = (V, E)$ is a finite simple graph on $V = \{1, \dots, n\}$; adjacency is
symmetric and irreflexive.

\begin{definition}[Simply-laced Cartan matrix]
The generalized Cartan matrix associated with $G$ is $A \in \mathbb{Z}^{V\times V}$ with
$A_{ij} = 2$ if $i = j$, $A_{ij} = -1$ if $i \sim j$, and $A_{ij} = 0$ otherwise. Equivalently
$A = 2\,\Id - \Adj(G)$, and $A_{ij} = \pair{\alpha_j}{\coroot{i}}$.
\end{definition}

\begin{definition}[Partial root sum]
For $S \subseteq V$, set $\beta_S = \sum_{j \in S} \alpha_j$.
\end{definition}

\begin{definition}[Coroot pairing]
For $S \subseteq V$ and $i \in V$, $\pair{\beta_S}{\coroot{i}} = \sum_{j \in S} A_{ij}$.
\end{definition}

\begin{definition}[Degree into a set]
For $S \subseteq V$ and $i \in V$, $\deg_S i = \#\{\, j \in S : i \sim j \,\}$ is the number of
neighbors of $i$ inside $S$. When $S = V$ this is the ordinary degree $\deg i$, and in general
$0 \le \deg_S i \le \deg i$.
\end{definition}

\begin{definition}[The weight $\lambda_{D,I}$ and dominance]
With the normalization $\pair{\rho}{\coroot{i}} = 1$ for all $i$, the $i$-th coordinate of
$\lambda_{D,I} = 2\rho - \beta_I - \beta_D$ is
$\pair{\lambda_{D,I}}{\coroot{i}} = 2 - \pair{\beta_I}{\coroot{i}} - \pair{\beta_D}{\coroot{i}}$.
The weight is \emph{dominant}, written $\lambda_{D,I} \in \Pplus$, if
$\pair{\lambda_{D,I}}{\coroot{i}} \ge 0$ for every $i \in V$.
\end{definition}

\section{The pairing formulas}

\begin{lemma}[Off-diagonal sum]\label{lem:off}
For any $S \subseteq V$ and $i \in V$, $\sum_{x \in S \setminus \{i\}} A_{ix} = -\deg_S i.$
\end{lemma}

\begin{proof}
For $x \ne i$, $A_{ix} = -1$ when $i \sim x$ and $0$ otherwise. By irreflexivity, removing $i$
from $S$ does not change the neighbor count, so the sum equals
$-\#\{x \in S : i \sim x\} = -\deg_S i$.
\end{proof}

\begin{theorem}[Closed-form pairings]\label{thm:pair}
For $S \subseteq V$ and $i \in V$,
\[
\pair{\beta_S}{\coroot{i}} =
\begin{cases} 2 - \deg_S i, & i \in S,\\ -\deg_S i, & i \notin S.\end{cases}
\]
\end{theorem}

\begin{proof}
If $i \in S$, split off the diagonal: $\pair{\beta_S}{\coroot{i}} = A_{ii} + \sum_{x \in
S\setminus\{i\}} A_{ix} = 2 - \deg_S i$ by Lemma~\ref{lem:off}. If $i \notin S$, then
$S \setminus \{i\} = S$ and the sum is $-\deg_S i$.
\end{proof}

\section{The dominance criterion}

We specialize to $I = V$, so $\beta_I = \sum_{j\in V}\alpha_j$ and $\deg_I i = \deg i$.

\begin{theorem}[Dominance criterion, whole diagram]\label{thm:dom}
For any $D \subseteq V$,
\[
\lambda_{D,V} \in \Pplus \iff \forall\, i \in D,\ \deg i + \deg_D i \ge 2.
\]
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:pair} with $S = V$ (and $i \in V$ always),
$\pair{\lambda_{D,V}}{\coroot{i}} = 2 - (2 - \deg i) - \pair{\beta_D}{\coroot{i}}
= \deg i - \pair{\beta_D}{\coroot{i}}$. If $i \in D$, then
$\pair{\beta_D}{\coroot{i}} = 2 - \deg_D i$, giving $\deg i + \deg_D i - 2$, nonnegative iff
$\deg i + \deg_D i \ge 2$. If $i \notin D$, then $\pair{\beta_D}{\coroot{i}} = -\deg_D i$, giving
$\deg i + \deg_D i \ge 0$ unconditionally.
\end{proof}

In uniform form,
\[
\pair{\lambda_{D,V}}{\coroot{i}} = \deg i + \deg_D i - 2\cdot[\,i \in D\,].
\]

\begin{proposition}[Empty marking]\label{prop:empty}
$\lambda_{\varnothing, V} = 2\rho - \beta_V$ is always dominant.
\end{proposition}

\begin{proof}
The criterion of Theorem~\ref{thm:dom} quantifies over $i \in \varnothing$ and holds vacuously.
\end{proof}

\begin{proposition}[Minimum-degree sufficient condition]\label{prop:mindeg}
If every $i \in D$ has $\deg i \ge 2$, then $\lambda_{D,V}$ is dominant.
\end{proposition}

\begin{proof}
Since $\deg_D i \ge 0$, the hypothesis gives $\deg i + \deg_D i \ge 2$; apply
Theorem~\ref{thm:dom}.
\end{proof}

\begin{theorem}[Leaf obstruction]\label{thm:leaf}
For a single vertex $v$, $\lambda_{\{v\}, V} \in \Pplus \iff \deg v \ge 2$. In particular a leaf
($\deg v = 1$) or isolated vertex never carries a dominant singleton.
\end{theorem}

\begin{proof}
With $D = \{v\}$, irreflexivity gives $\deg_D v = 0$, so Theorem~\ref{thm:dom} reads
$\deg v \ge 2$.
\end{proof}

\begin{remark}[Rescue by adjacency]
The criterion depends on $\deg i + \deg_D i$, not on $\deg i$ alone. A degree-one vertex is
forbidden as a singleton, but if its unique neighbor is also marked then $\deg_D i = 1$ and
$\deg i + \deg_D i = 2$, so the marking becomes admissible in that direction. Dominance is a
global property of $D$.
\end{remark}

\section{Forests as the frontier}

\begin{theorem}[Forest characterization]\label{thm:forest}
Let $G$ be a finite connected simple graph with at least two vertices. The following are
equivalent: (1) every vertex carries a dominant singleton; (2) every vertex has degree $\ge 2$;
(3) $G$ contains a cycle. Consequently, the connected diagrams on which some vertex fails to
carry a dominant singleton are exactly the trees.
\end{theorem}

\begin{proof}
(1)$\iff$(2) is Theorem~\ref{thm:leaf} applied to each vertex. For (2)$\iff$(3): a connected
finite graph is a tree iff it has a vertex of degree $\le 1$ (a leaf); equivalently, minimum
degree $\ge 2$ holds iff the graph is not a tree, i.e.\ contains a cycle. Combining, failure of
(1) characterizes trees among connected graphs.
\end{proof}

This reframes the ambient hypothesis that $I$ carry no cycle of length $\ge 3$: acyclicity of $I$
is precisely the regime where the singleton dominance test is nontrivial.

\section{Worked examples}

\begin{example}[Path $P_3$: $1 - 2 - 3$]
Degrees $1,2,1$. Singleton $\{2\}$ is dominant; $\{1\},\{3\}$ are not. Marking $D=\{1,2\}$ is
admissible: vertex $1$ has $\deg 1 + \deg_D 1 = 1 + 1 = 2$, vertex $2$ has $2 + 1 = 3$.
\end{example}

\begin{example}[Cycle $C_4$]
Every degree is $2$, so every nonempty subset is dominant, consistent with
Theorem~\ref{thm:forest}.
\end{example}

\begin{example}[Star $K_{1,3}$]
Only the center yields a dominant singleton; a leaf becomes admissible in its own coordinate only
when the center is also marked.
\end{example}

\section{Discussion}

The reduction is faithful (it re-expresses dominance exactly), decidable (linear-time from
adjacency data), and explanatory (the leaf obstruction and forest dichotomy show why acyclicity
is natural). The identity
$\pair{\lambda_{D,V}}{\coroot{i}} = \deg i + \deg_D i - 2[\,i\in D\,]$ is the reusable engine,
localizing dominance to marked vertices and revealing the degree-sum as the governing invariant.

\section{Conclusion}

In the simply-laced case, dominance of $\lambda_{D,I} = 2\rho - \beta_I - \beta_D$ is governed
entirely by vertex degrees: for the whole diagram, dominance holds iff every marked vertex
satisfies $\deg i + \deg_D i \ge 2$; singletons obey the leaf obstruction $\deg v \ge 2$; the
empty marking is always dominant; and forests are the exact frontier at which singleton
dominance can fail.

\end{document}

